-- Function: public.fn_get_authorized_pickups
-- Backup generated on 2026-10-25 20:33:02

CREATE OR REPLACE FUNCTION public.fn_get_authorized_pickups(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(id uuid, child_id uuid, person_id uuid, relationship character varying, pickup_code character varying, photo_url text, is_active boolean, notes character varying, full_name character varying, phone character varying)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT ap.id, ap.child_id, ap.person_id, ap.relationship::VARCHAR, ap.pickup_code::VARCHAR,            ap.photo_url::TEXT, ap.is_active, ap.notes::VARCHAR,            COALESCE(NULLIF(TRIM(p.first_name || ' ' || p.last_name), ''), ap.relationship, 'Authorized Pickup')::VARCHAR AS full_name,            COALESCE(p.mobile_phone, p.alternate_phone)::VARCHAR AS phone     FROM authorized_pickups ap     LEFT JOIN persons p ON ap.person_id = p.id     WHERE ap.tenant_id = p_tenant_id AND ap.child_id = p_child_id AND ap.is_active = TRUE     ORDER BY ap.is_active DESC; END; $function$ ;
